PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE session(id text primary key, project_id text not null, slug text not null, directory text not null, title text not null, version text not null, time_created integer not null, time_updated integer not null);
CREATE TABLE message(id text primary key, session_id text not null references session(id) on delete cascade, time_created integer not null, time_updated integer not null, data text not null, sequence integer);
CREATE TABLE part(id text primary key, message_id text not null, session_id text not null, time_created integer not null, time_updated integer not null, data text not null);
CREATE TABLE model_usage(id text primary key, logical_request_id text not null, attempt_index integer not null default 0, session_id text not null references session(id) on delete cascade, turn_id text, trace_id text, span_id text, assistant_message_id text, parent_user_message_id text, query_source text not null, provider_id text not null, model_id text not null, variant text, agent text, mode text, task_type text, status text not null check(status in ('running', 'completed', 'error', 'cancelled')), started_at integer not null, first_token_at integer, completed_at integer, duration_ms integer, time_to_first_token_ms integer, finish_reason text, tool_call_count integer not null default 0, input_tokens integer not null default 0, output_tokens integer not null default 0, reasoning_tokens integer not null default 0, cache_creation_input_tokens integer not null default 0, cache_read_input_tokens integer not null default 0, provider_total_tokens integer, computed_total_tokens integer not null default 0, retry_count integer not null default 0, retryable integer not null default 0 check(retryable in (0, 1)), cancelled_by_user integer not null default 0 check(cancelled_by_user in (0, 1)), context_exceeded integer not null default 0 check(context_exceeded in (0, 1)), error_type text, error_code text, error_message text, raw_usage_json text, provider_metadata_json text);
COMMIT;
